import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_src = r'''
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>
#include <cuda_bf16.h>
#include <stdint.h>

template<typename T> __device__ __forceinline__ float cvt_float(T v);
template<> __device__ __forceinline__ float cvt_float<float>(float v) { return v; }
template<> __device__ __forceinline__ float cvt_float<__half>(__half v) { return __half2float(v); }
template<> __device__ __forceinline__ float cvt_float<__nv_bfloat16>(__nv_bfloat16 v) { return __bfloat162float(v); }

template<typename T> __device__ __forceinline__ T cvt_from_float(float v);
template<> __device__ __forceinline__ float cvt_from_float<float>(float v) { return v; }
template<> __device__ __forceinline__ __half cvt_from_float<__half>(float v) { return __float2half_rn(v); }
template<> __device__ __forceinline__ __nv_bfloat16 cvt_from_float<__nv_bfloat16>(float v) { return __float2bfloat16_rn(v); }

template<typename T>
__device__ __forceinline__ T make_out(float xv, float inv, T wv) {
    T norm_t = cvt_from_float<T>(xv * inv);
    float out = cvt_float<T>(norm_t) * cvt_float<T>(wv);
    return cvt_from_float<T>(out);
}

template<>
__device__ __forceinline__ float make_out<float>(float xv, float inv, float wv) {
    return (xv * inv) * wv;
}

__device__ __forceinline__ float warp_sum(float v) {
    unsigned mask = 0xffffffffu;
    v += __shfl_down_sync(mask, v, 16);
    v += __shfl_down_sync(mask, v, 8);
    v += __shfl_down_sync(mask, v, 4);
    v += __shfl_down_sync(mask, v, 2);
    v += __shfl_down_sync(mask, v, 1);
    return v;
}

__device__ __forceinline__ float block_sum(float v) {
    __shared__ float smem[32];
    int lane = threadIdx.x & 31;
    int wid = threadIdx.x >> 5;
    v = warp_sum(v);
    if (lane == 0) smem[wid] = v;
    __syncthreads();
    float total = (threadIdx.x < ((blockDim.x + 31) >> 5)) ? smem[lane] : 0.0f;
    if (wid == 0) total = warp_sum(total);
    if (threadIdx.x == 0) smem[0] = total;
    __syncthreads();
    return smem[0];
}

template<typename T, int WARPS_PER_BLOCK>
__global__ __launch_bounds__(WARPS_PER_BLOCK*32, 4)
void rms_warp_kernel(const T* __restrict__ x, const T* __restrict__ w, T* __restrict__ y, int N, int D) {
    int tid = threadIdx.x;
    int lane = tid & 31;
    int warp_in_block = tid >> 5;
    int row = blockIdx.x * WARPS_PER_BLOCK + warp_in_block;
    if (row >= N) return;
    size_t base = (size_t)row * (size_t)D;
    float ss = 0.0f;
    for (int col = lane; col < D; col += 32) {
        float xv = cvt_float<T>(x[base + col]);
        ss = fmaf(xv, xv, ss);
    }
    ss = warp_sum(ss);
    float inv = rsqrtf(ss / (float)D + 1.0e-6f);
    for (int col = lane; col < D; col += 32) {
        float xv = cvt_float<T>(x[base + col]);
        T wv = w[col];
        y[base + col] = make_out<T>(xv, inv, wv);
    }
}

template<typename T, int THREADS>
__global__ __launch_bounds__(THREADS, 3)
void rms_block_kernel(const T* __restrict__ x, const T* __restrict__ w, T* __restrict__ y, int N, int D) {
    int row = blockIdx.x;
    if (row >= N) return;
    size_t base = (size_t)row * (size_t)D;
    float ss = 0.0f;
    for (int col = threadIdx.x; col < D; col += THREADS) {
        float xv = cvt_float<T>(x[base + col]);
        ss = fmaf(xv, xv, ss);
    }
    float total = block_sum(ss);
    float inv = rsqrtf(total / (float)D + 1.0e-6f);
    for (int col = threadIdx.x; col < D; col += THREADS) {
        float xv = cvt_float<T>(x[base + col]);
        T wv = w[col];
        y[base + col] = make_out<T>(xv, inv, wv);
    }
}

template<typename T>
void launch_typed(const T* x, const T* w, T* y, int N, int D, cudaStream_t stream) {
    if (D <= 1024) {
        constexpr int WPB = 8;
        dim3 block(WPB * 32);
        dim3 grid((N + WPB - 1) / WPB);
        rms_warp_kernel<T, WPB><<<grid, block, 0, stream>>>(x, w, y, N, D);
    } else {
        constexpr int TH = 256;
        dim3 block(TH);
        dim3 grid(N);
        rms_block_kernel<T, TH><<<grid, block, 0, stream>>>(x, w, y, N, D);
    }
}

torch::Tensor rms_forward(torch::Tensor x, torch::Tensor w) {
    TORCH_CHECK(x.is_cuda(), "x must be CUDA");
    TORCH_CHECK(w.is_cuda(), "w must be CUDA");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(w.dim() == 1, "w must be 1D");
    TORCH_CHECK(x.size(1) == w.size(0), "dimension mismatch");
    TORCH_CHECK(x.scalar_type() == w.scalar_type(), "dtype mismatch");
    auto y = torch::empty_like(x);
    int64_t N64 = x.size(0), D64 = x.size(1);
    TORCH_CHECK(N64 <= INT_MAX && D64 <= INT_MAX, "shape too large");
    int N = (int)N64, D = (int)D64;
    if (N == 0 || D == 0) return y;
    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    auto st = x.scalar_type();
    if (st == at::kFloat) {
        launch_typed<float>((const float*)x.data_ptr<float>(), (const float*)w.data_ptr<float>(), (float*)y.data_ptr<float>(), N, D, stream);
    } else if (st == at::kHalf) {
        launch_typed<__half>((const __half*)x.data_ptr<at::Half>(), (const __half*)w.data_ptr<at::Half>(), (__half*)y.data_ptr<at::Half>(), N, D, stream);
    } else if (st == at::kBFloat16) {
        launch_typed<__nv_bfloat16>((const __nv_bfloat16*)x.data_ptr<at::BFloat16>(), (const __nv_bfloat16*)w.data_ptr<at::BFloat16>(), (__nv_bfloat16*)y.data_ptr<at::BFloat16>(), N, D, stream);
    } else {
        TORCH_CHECK(false, "unsupported dtype");
    }
    return y;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("rms_forward", &rms_forward, "RMS layernorm forward");
}
